/**
 * Ticket #24 acceptance test — the contract for aligning the downscale grid with the source's pixel grid.
 * Do not edit this file to make it pass.
 */
import { describe, expect, it } from 'vitest';
import { fitCells, type FitCellsOptions } from '../../scripts/lib/gemini-art';
import type { PngImage } from '../../scripts/lib/png';

type Pixel = readonly [number, number, number, number];
const CLEAR: Pixel = [0, 0, 0, 0];
const STRAY: Pixel = [143, 62, 86, 255];
const EYE: Pixel = [20, 27, 27, 255];
const SKIN: Pixel = [252, 226, 202, 255];
const HAIR: Pixel = [59, 54, 67, 255];
const ROBE: readonly Pixel[] = [
  [242, 234, 241, 255],
  [184, 220, 229, 255],
  [45, 105, 123, 255],
];
const P = 18; // source pixels per output pixel (scale 1/18), = 3 native blocks of 6 px
const NW = 10; // sprite width in output pixels
const NH = 15; // sprite height in output pixels
const EYES: ReadonlyArray<readonly [number, number]> = [
  [2, 4],
  [7, 4],
];

/**
 * The sprite as it should come out, one colour per output pixel: hair on top and at the
 * sides, a skin face with two eyes, a robe of varying colours below.
 */
function expected(x: number, y: number): Pixel {
  if (EYES.some(([ex, ey]) => ex === x && ey === y)) return EYE;
  if (y < 2) return HAIR;
  if (y < 9) return x === 0 || x === NW - 1 ? HAIR : SKIN;
  return ROBE[(x * 7 + y * 3) % ROBE.length]!;
}

function canvas(width: number, height: number): PngImage {
  const data = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i += 1) data.set(CLEAR, i * 4);
  return { width, height, data };
}

function rect(image: PngImage, x0: number, y0: number, w: number, h: number, p: Pixel): void {
  for (let y = y0; y < y0 + h; y += 1) for (let x = x0; x < x0 + w; x += 1) image.data.set(p, (y * image.width + x) * 4);
}

/**
 * Draw the sprite at (ox, oy), every output pixel an 18 px square, except that each eye
 * is only 12 px wide (2 of the 3 native blocks; skin fills the rest of its square), like
 * a Gemini eye that is narrower than one output pixel. A 1 px stray line 12 px left of
 * the sprite moves the bounding box off the sprite's grid by two native blocks; one 6 px
 * right of it makes the union window a whole number of output pixels wide.
 */
function drawSprite(image: PngImage, ox: number, oy: number): void {
  for (let y = 0; y < NH; y += 1) {
    for (let x = 0; x < NW; x += 1) {
      const colour = expected(x, y);
      if (colour === EYE) {
        rect(image, ox + x * P, oy + y * P, P, P, SKIN);
        rect(image, ox + x * P, oy + y * P, 12, P, EYE);
      } else {
        rect(image, ox + x * P, oy + y * P, P, P, colour);
      }
    }
  }
  rect(image, ox - 12, oy, 1, NH * P, STRAY);
  rect(image, ox + NW * P + 5, oy, 1, NH * P, STRAY);
}

/** Frame-local positions where the expected sprite appears pixel for pixel in frame (column 0, `row`). */
function nativeAt(sheet: PngImage, row: number, frame: number): Array<[number, number]> {
  const found: Array<[number, number]> = [];
  for (let fy = 0; fy + NH <= frame; fy += 1) {
    for (let fx = 0; fx + NW <= frame; fx += 1) {
      let same = true;
      for (let y = 0; y < NH && same; y += 1) {
        for (let x = 0; x < NW && same; x += 1) {
          const i = ((row * frame + fy + y) * sheet.width + fx + x) * 4;
          const want = expected(x, y);
          for (let k = 0; k < 4; k += 1) if (sheet.data[i + k] !== want[k]) same = false;
        }
      }
      if (same) found.push([fx, fy]);
    }
  }
  return found;
}

function bottomRow(sheet: PngImage, row: number, frame: number): number {
  let last = -1;
  for (let y = 0; y < frame; y += 1) {
    for (let x = 0; x < sheet.width; x += 1) if (sheet.data[((row * frame + y) * sheet.width + x) * 4 + 3]! >= 128) last = y;
  }
  return last;
}

// One direction column, two frames; frame 2 is frame 1 moved right by exactly one output pixel.
// The union window is 28..244 × 10..280 (left stray line of frame 1 to right stray line of
// frame 2): 216 × 270 px, which fits the 15 px feet box at scale 1/18 as 12 × 15 px. Today the grid starts at the stray line, 12 px off the
// sprite's grid, so each eye covers only 6/18 of two output pixels and the skin wins both.
function source(): PngImage {
  const image = canvas(256, 600);
  drawSprite(image, 40, 10);
  drawSprite(image, 40 + P, 300 + 10);
  return image;
}

function eyePixels(sheet: PngImage): number {
  let count = 0;
  for (let i = 0; i < sheet.data.length; i += 4) {
    if (sheet.data[i] === EYE[0] && sheet.data[i + 1] === EYE[1] && sheet.data[i + 2] === EYE[2] && sheet.data[i + 3]! >= 128) count += 1;
  }
  return count;
}

const BASE: FitCellsOptions = { columns: 1, rows: 2, frameWidth: 16, frameHeight: 16, anchor: 'feet', share: 'column' };

describe('#24 grid alignment', () => {
  it('today’s fit (no alignment) loses every eye', () => {
    expect(eyePixels(fitCells(source(), BASE))).toBe(0);
  });

  it('keeps both eyes in both frames when aligned', () => {
    expect(eyePixels(fitCells(source(), { ...BASE, align: true }))).toBe(4);
  });

  it('reproduces the sprite pixel for pixel when aligned', () => {
    const sheet = fitCells(source(), { ...BASE, align: true });
    expect(nativeAt(sheet, 0, 16)).toHaveLength(1);
    expect(nativeAt(sheet, 1, 16)).toHaveLength(1);
  });

  it('uses one offset for the whole column, so frame 2 stays one pixel right of frame 1', () => {
    const sheet = fitCells(source(), { ...BASE, align: true });
    const [first] = nativeAt(sheet, 0, 16);
    const [second] = nativeAt(sheet, 1, 16);
    expect(second).toEqual([first![0] + 1, first![1]]);
  });

  it('keeps the output inside the frame with the feet on the floor', () => {
    const sheet = fitCells(source(), { ...BASE, align: true });
    expect([sheet.width, sheet.height]).toEqual([16, 32]);
    expect(bottomRow(sheet, 0, 16)).toBe(15);
    expect(bottomRow(sheet, 1, 16)).toBe(15);
  });

  it('changes nothing when align is off', () => {
    const image = source();
    expect(Buffer.compare(fitCells(image, BASE).data, fitCells(image, { ...BASE, align: false }).data)).toBe(0);
  });
});
